<template>
 <div class="friends-backdrop" data-social-surface @mousedown.stop @click.self="$emit('close')" @keydown.esc.stop.prevent="closeOrBack" @keydown.tab="trapFocus" @keyup.stop>
  <section ref="panel" class="friends-panel" role="dialog" aria-modal="true" aria-labelledby="friends-title">
   <header><div class="friends-brand"><journal-icon name="friends"/><div><small>LE CARNET DES DRESSEURS</small><h2 id="friends-title">Tes amis <span>{{ state.accepted.filter(p=>p.online&&!p.afk).length }} en ligne</span></h2></div></div><button ref="close" data-gamepad-back aria-label="Fermer les amis" @click="$emit('close')">×</button></header>
   <p v-if="!connected" class="friends-notice" role="status">Connexion interrompue. Ton carnet reste ouvert.</p><p v-if="error||serverError" class="friends-error" role="alert">{{ error||serverError }}</p><p v-if="notice" class="friends-notice" role="status">{{ notice }}</p>
   <div v-if="tradeInvite" class="friend-trade-invite" data-friend-trade-invite><p><strong>{{ tradeInvite.participants.find(p=>p.id===tradeInvite.requestedBy)?.username || 'Un ami' }}</strong> te propose un échange.</p><button data-trade-accept :disabled="trading||!connected||!canTrade" @click="$emit('trade-answer',true)">Accepter</button><button data-trade-decline :disabled="trading||!connected" @click="$emit('trade-answer',false)">Refuser</button><small v-if="!canTrade">Disponible hors combat en Aventure.</small></div>
   <div class="friends-layout" :class="{'has-conversation':!!selected}">
    <aside class="friends-directory" aria-label="Tes amis">
     <div class="friend-list-heading"><h3>Tes amis</h3><span>{{ state.accepted.length }}</span></div>
     <article v-for="p in sortedFriends" :key="p.id" class="friend-row" :class="{selected:selected?.id===p.id,'has-unread':p.unread>0}" :data-friend-row="p.id" :style="friendStyle(p)">
      <button class="friend-info" :data-social-friend="p.id" @click="selectTrainer(p)"><span class="friend-avatar" aria-hidden="true">{{ p.username.slice(0,1).toUpperCase() }}</span><span><strong :title="p.username"><presence-dot :person="p" :connected="connected"/><span class="friend-label">{{ p.username }}</span></strong><small>{{ status(p) }}</small><small v-if="connected&&p.online" class="friend-session" :data-session-since="p.id">{{ duration(p) }}</small></span></button>
      <div class="friend-actions" :aria-label="`Carnet de ${p.username}`"><button v-for="action in actions" :key="action.key" :data-friend-action="action.key" :aria-label="`${action.label} de ${p.username}`" :title="action.label" :aria-pressed="selected?.id===p.id&&view===action.key" @click="selectTrainer(p,action.key)"><journal-icon :name="action.icon"/><notification-badge v-if="action.key==='messages'" :count="Number(p.unread)||0"/></button><button data-friend-action="trade" :aria-label="`Proposer un échange à ${p.username}`" title="Échanger · équipe, PC ou objets" :disabled="busy||trading||!connected||!canTrade||!p.online" @click="askTrade(p)"><journal-icon name="exchange"/></button><button data-friend-action="flight" :aria-label="`Rejoindre ${p.username}`" title="Rejoindre avec le Module Vol" :disabled="busy||!connected||!p.online" @click="flyFriend(p)"><journal-icon name="flight"/></button><button data-friend-action="color" :aria-label="`Couleur de ${p.username}`" title="Couleur personnelle" :aria-expanded="colorTarget===p.id" @click="colorTarget=colorTarget===p.id?null:p.id"><journal-icon name="palette"/></button></div>
      <div v-if="colorTarget===p.id" class="friend-palette" :aria-label="`Choisir la couleur de ${p.username}`"><small>Couleur personnelle</small><button v-for="(color,key) in colors" :key="key" :data-friend-color="key" :style="{backgroundColor:color}" :aria-label="colorNames[key]" :aria-pressed="p.color===key" :disabled="busy||!connected" @click="setColor(p,key)"><span v-if="p.color===key" aria-hidden="true">✓</span></button><button class="friend-color-reset" :disabled="busy||!connected" @click="setColor(p,null)">Par défaut</button></div>
     </article>
     <p v-if="!state.accepted.length" class="friends-empty">Tes compagnons de route apparaîtront ici. Retrouve les autres dresseurs en bas du carnet.</p>
     <section v-if="state.incoming.length" class="friend-requests"><h3>Demandes reçues <notification-badge :count="state.incoming.length"/></h3><div v-for="p in state.incoming" :key="p.id" class="friend-entry"><strong>{{ p.username }}</strong><div><button :data-social-accept="p.id" :disabled="busy||!connected" @click="friendAction(p.id,'accept')">Accepter</button><button :disabled="busy||!connected" @click="friendAction(p.id,'decline')">Refuser</button></div></div></section>
     <section v-if="state.outgoing.length" class="friend-requests"><h3>Demandes envoyées</h3><div v-for="p in state.outgoing" :key="p.id" class="friend-entry"><strong>{{ p.username }}</strong><button :disabled="busy||!connected" @click="friendAction(p.id,'cancel')">Annuler</button></div></section>
    </aside>
    <main class="friend-content">
     <template v-if="selected">
      <div class="conversation-heading"><button class="friends-back" data-social-back @click="selected=null">‹ Amis</button><div><h3><presence-dot :person="selectedProfile" :connected="connected"/>{{ selected.username }}</h3><small>{{ status(selectedProfile) }}<template v-if="connected&&selectedProfile.online"> · {{ duration(selectedProfile) }}</template></small></div><button v-if="relation(selected.id)==='friends'" data-selected-friend-flight :disabled="busy||!connected||!selectedProfile.online" title="Rejoindre avec le Module Vol" aria-label="Rejoindre cet ami" @click="flyFriend(selectedProfile)"><journal-icon name="flight"/></button><button v-if="relation(selected.id)==='friends'" data-friend-trade :disabled="busy||trading||!connected||!canTrade||!selectedProfile.online" @click="askTrade">Échanger</button></div>
      <template v-if="relation(selected.id)==='friends'">
       <nav class="friend-view-tabs" aria-label="Carnet de l’ami"><button v-for="action in actions" :key="action.key" :aria-pressed="view===action.key" :data-friend-view="action.key" @click="view=action.key"><journal-icon :name="action.icon"/><span>{{ action.label }}</span></button></nav>
       <private-chat v-if="view==='messages'" :key="selected.id" :friend="selectedProfile" :user-id="userId" :connected="connected" :incoming-message="incomingMessage" :command="command" :saved-draft="drafts[selected.id]||''" :saved-conversation="conversations[selected.id]" @conversation="$emit('conversation',$event)" @draft="$emit('draft',$event)" @reading="$emit('reading',$event)"/>
       <friend-collection v-else :key="selected.id" :friend="selectedProfile" :view="view" :command="command"/>
       <button class="friend-remove" data-social-remove :disabled="busy||!connected" @click="removeConfirmation=true">Retirer cet ami</button>
       <div v-if="removeConfirmation" class="friends-confirm" role="alertdialog" aria-label="Retirer cet ami"><p>Retirer {{ selected.username }} de tes amis ?</p><button @click="removeConfirmation=false">Garder cet ami</button><button :disabled="busy" @click="friendAction(selected.id,'remove')">Retirer</button></div>
      </template>
      <div v-else class="friends-welcome"><journal-icon name="friends"/><h3>{{ selected.username }}</h3><p>{{ relationshipLabel(relation(selected.id)) }}</p><button v-if="relation(selected.id)==='none'" :disabled="busy||!connected" :data-social-add="selected.id" @click="friendAction(selected.id,'request')">Ajouter en ami</button><button v-else-if="relation(selected.id)==='incoming'" :disabled="busy||!connected" @click="friendAction(selected.id,'accept')">Accepter la demande</button></div>
     </template>
     <div v-else class="friends-welcome"><journal-icon name="friends"/><h3>Garde le contact</h3><p>Un message, un badge, une place au classement.</p><p>Tes amis sont visibles sur la minimap, même sans voyager ensemble.</p></div>
    </main>
   </div>
   <footer class="friends-discovery" :class="{'is-open':tab==='online'}">
    <button class="discovery-toggle" data-social-tab="online" :aria-expanded="tab==='online'" aria-controls="friends-discovery-content" @click="changeTab(tab==='online'?'friends':'online')"><journal-icon name="user"/><span>Dresseurs connectés <small>Retrouver ou ajouter un dresseur</small></span><span aria-hidden="true">{{ tab==='online'?'⌄':'›' }}</span></button>
    <div v-if="tab==='online'" id="friends-discovery-content" class="discovery-content">
     <label>Chercher un dresseur<input v-model="query" data-social-search type="search" maxlength="50" placeholder="Pseudo · 2 caractères minimum" :disabled="!connected" @input="scheduleSearch"/></label>
     <div class="discovery-results" :aria-busy="searching||onlineLoading">
      <p v-if="searching||onlineLoading" class="friends-empty" role="status">Recherche…</p><p v-else-if="!(query.trim().length>=2?results:onlineEntries).length" class="friends-empty">{{ query.trim().length>=2?'Aucun dresseur trouvé.':'Aucun autre dresseur connecté.' }}</p>
      <div v-for="p in query.trim().length>=2?results:onlineEntries" :key="p.id" class="friend-entry" :data-social-online="query.trim().length<2?p.id:null" :data-social-result="query.trim().length>=2?p.id:null"><button class="friend-name" @click="selectTrainer(p)"><presence-dot :person="p" :connected="connected"/><span>{{ p.username }}<small>{{ status(p) }}</small></span></button><button v-if="relation(p.id)==='none'" :data-social-online-add="query.trim().length<2?p.id:null" :data-social-search-add="query.trim().length>=2?p.id:null" :disabled="busy||!connected" @click="friendAction(p.id,'request')">Ajouter</button><button v-else-if="relation(p.id)==='incoming'" :disabled="busy||!connected" @click="friendAction(p.id,'accept')">Accepter</button><small v-else>{{ relationshipLabel(relation(p.id)) }}</small></div>
      <button v-if="query.trim().length>=2?searchMore:onlineMore" class="directory-more" :data-social-search-more="query.trim().length>=2?'':null" :data-social-online-more="query.trim().length<2?'':null" :disabled="searching||onlineLoading||!connected" @click="query.trim().length>=2?loadMoreSearch():loadOnline(true)">Afficher plus</button>
     </div>
    </div>
   </footer>
  </section>
 </div>
</template>
<script>
import JournalIcon from '../menu/JournalIcon.vue';
import NotificationBadge from './NotificationBadge.vue';
import PresenceDot from './PresenceDot.vue';
import PrivateChat from './PrivateChat.vue';
import FriendCollection from './FriendCollection.vue';
import {FRIEND_COLORS,friendColorStyle} from '@/services/friendColors';
import {presenceLabel,sessionDuration} from '@/services/friendPresence';
export default{
 components:{JournalIcon,NotificationBadge,PresenceDot,PrivateChat,FriendCollection},
 props:{tradeInvite:Object,trading:Boolean,canTrade:Boolean,requestTrade:Function,requestFlight:Function,conversations:{type:Object,default:()=>({})},state:{type:Object,required:true},presenceRevision:Number,userId:Number,connected:Boolean,serverError:String,initialTarget:Object,incomingMessage:Object,command:{type:Function,required:true},drafts:{type:Object,default:()=>({})}},
 data(){return{colors:FRIEND_COLORS,colorNames:{blue:'Bleu',sage:'Sauge',lavender:'Lavande',sand:'Sable',rose:'Rose',coral:'Corail',teal:'Turquoise',slate:'Ardoise'},colorTarget:null,tab:'friends',view:'messages',query:'',results:[],searching:false,searchMore:false,searchOffset:0,onlineEntries:[],onlineLoading:false,onlineMore:false,onlineOffset:0,onlineTotal:0,selected:null,busy:false,error:'',notice:'',removeConfirmation:false,previousFocus:null,clock:Date.now(),clockOffset:(this.state.serverNow||Date.now())-Date.now(),actions:[{key:'messages',label:'Messages',icon:'messages'},{key:'badges',label:'Badges',icon:'badges'},{key:'rankings',label:'Classements',icon:'ranking'}]};},
 computed:{sortedFriends(){return [...this.state.accepted].sort((a,b)=>Number(b.online&&!b.afk)-Number(a.online&&!a.afk)||Number(b.online)-Number(a.online)||a.username.localeCompare(b.username,'fr'));},selectedProfile(){return this.state.accepted.find(p=>p.id===this.selected?.id)||this.selected;}},
 watch:{presenceRevision(){this.refreshDiscovery();},'state.serverNow'(v){if(v)this.clockOffset=v-Date.now();},connected(value){if(value)this.refreshDiscovery();else{this.cancelDiscovery();this.results=[];this.onlineEntries=[];this.onlineTotal=0;this.onlineMore=false;this.searchMore=false;}},tab(value){if(value==='online')this.refreshDiscovery();else this.cancelDiscovery();},'state.accepted'(next,previous){if(this.selected&&previous?.some(p=>p.id===this.selected.id)&&!next.some(p=>p.id===this.selected.id)){this.view='messages';this.removeConfirmation=false;}},initialTarget(p){if(p)this.selectTrainer(p);}},
 mounted(){this.previousFocus=document.activeElement;this.$refs.close.focus({preventScroll:true});if(this.initialTarget)this.selectTrainer(this.initialTarget);this.clockTimer=setInterval(()=>this.clock=Date.now(),15000);},
 beforeDestroy(){clearInterval(this.clockTimer);this.cancelDiscovery();this.$emit('reading',null);const previous=this.previousFocus;this.$nextTick(()=>{(previous?.isConnected?previous:document.querySelector('.menu-toggle-btn'))?.focus({preventScroll:true});});},
 methods:{
  friendStyle:friendColorStyle,
  async setColor(p,color){const r=await this.run('social:color',{targetId:p.id,color},'Couleur sauvegardée.');if(r)this.colorTarget=null;},
  async flyFriend(p){this.error='';try{await this.requestFlight(p);}catch(e){this.error=e.message;}},
  status(p){return presenceLabel(p,this.connected);},duration(p){return sessionDuration(p,this.clock+this.clockOffset);},
  changeTab(tab){this.tab=tab;},
  cancelDiscovery(){clearTimeout(this._searchTimer);clearTimeout(this._onlineTimer);this._searchVersion=(this._searchVersion||0)+1;this._onlineVersion=(this._onlineVersion||0)+1;this.searching=false;this.onlineLoading=false;},
  relation(id){return [...this.state.accepted,...this.state.incoming,...this.state.outgoing].find(p=>p.id===id)?.relationship||'none';},
  relationshipLabel(r){return{friends:'Amis',incoming:'Demande reçue',outgoing:'Demande envoyée',none:'Vous n’êtes pas encore amis.'}[r];},
  selectTrainer(p,view='messages'){this.selected={...p};this.view=view;this.error='';this.notice='';this.removeConfirmation=false;this.tab='friends';},
  async run(event,data={},notice=''){if(this.busy)return;this.busy=true;this.error='';this.notice='';try{const result=await this.command(event,data);this.notice=notice;return result;}catch(e){this.error=e.message;}finally{this.busy=false;}},
  async friendAction(id,action){const result=await this.run('social:friend',{targetId:id,action},{request:'Demande envoyée.',accept:'Vous êtes maintenant amis.',decline:'Demande refusée.',cancel:'Demande annulée.',remove:'Ami retiré.'}[action]);if(result)this.removeConfirmation=false;},
  async askTrade(person=this.selected){this.error='';try{await this.requestTrade(person.id);}catch(e){this.error=e.message;}},
  closeOrBack(){if(this.removeConfirmation){this.removeConfirmation=false;return;}if(this.selected&&window.innerWidth<=700){this.selected=null;return;}this.$emit('close');},
  trapFocus(e){const nodes=[...this.$refs.panel.querySelectorAll('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled)')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}},
    refreshDiscovery(){
      if(!this.connected||this.tab!=='online')return;
      if(this.query.trim().length>=2)this.scheduleSearch();
      clearTimeout(this._onlineTimer);this._onlineVersion=(this._onlineVersion||0)+1;
      this._onlineTimer=setTimeout(()=>this.loadOnline(),180);
    },
    async loadOnline(append=false){
      if(!this.connected||this.tab!=='online')return;
      const version=this._onlineVersion=(this._onlineVersion||0)+1,offset=append?this.onlineOffset:0,targetId=this.selected?.id;
      this.onlineLoading=true;
      try{const r=await this.command('social:online',{offset,...(targetId?{targetId}:{})});if(version!==this._onlineVersion)return;
        this.onlineEntries=[...new Map([...(append?this.onlineEntries:[]),...r.entries].map(p=>[p.id,p])).values()];
        this.onlineMore=Boolean(r.hasMore);this.onlineOffset=offset+20;this.onlineTotal=r.total;if(r.target&&r.target.id===this.selected?.id)Object.assign(this.selected,r.target);
      }catch(e){if(version===this._onlineVersion)this.error=e.message;}
      finally{if(version===this._onlineVersion)this.onlineLoading=false;}
    },
    scheduleSearch(){
      clearTimeout(this._searchTimer);const query=this.query.trim(),version=this._searchVersion=(this._searchVersion||0)+1;
      this.results=[];this.searchMore=false;this.error='';
      if(query.length<2){this.searching=false;this.loadOnline();return;}
      if(!this.connected||this.tab!=='online'){this.searching=false;return;}
      this.searching=true;this._searchTimer=setTimeout(()=>this.searchPage(query,version,0),300);
    },
    async searchPage(query,version,offset,append=false){
      this.searching=true;
      try{const r=await this.command('social:search',{query,offset});if(version!==this._searchVersion||query!==this.query.trim())return;
        this.results=[...new Map([...(append?this.results:[]),...r.entries].map(p=>[p.id,p])).values()];
        this.searchMore=Boolean(r.hasMore);this.searchOffset=offset+20;const selected=this.results.find(p=>p.id===this.selected?.id);if(selected)Object.assign(this.selected,selected);
      }catch(e){if(version===this._searchVersion)this.error=e.message;}
      finally{if(version===this._searchVersion)this.searching=false;}
    },
    loadMoreSearch(){if(this.searching||!this.searchMore||!this.connected)return;const version=this._searchVersion=(this._searchVersion||0)+1;return this.searchPage(this.query.trim(),version,this.searchOffset,true);},
 }
};
</script>
<style scoped>
